INSERT INTO research.source_usage_rights_v0
  (source_id, product_scope, use_case, rights_result, evidence_url, evidence_observed_on, rationale, scientific_model_admission, original_asset_admitted)
VALUES
  ('nl.rvo.brp-gewaspercelen.2025', 'RVO/PDOK BRP Gewaspercelen OGC API Features: exactly one current-live brpgewas Collection metadata GET on 2026-11-13, NOT immutable 2025 final parcel archive', 'internal_research', 'allowed', 'https://api.pdok.nl/rvo/gewaspercelen/ogc/v1?f=html&lang=en', DATE '2026-11-13', 'Exact public service/Collection metadata, provider identity, CRS and hash summaries may be inspected in a research context; this does not include farmer or parcel details, feature requests, or an original 2025 historical archive.', false, false),
  ('nl.rvo.brp-gewaspercelen.2025', 'RVO/PDOK BRP Gewaspercelen OGC API Features: exactly one current-live brpgewas Collection metadata GET on 2026-11-13, NOT immutable 2025 final parcel archive', 'commercial_cat_modelling', 'unknown', 'https://api.pdok.nl/rvo/gewaspercelen/ogc/v1?f=html&lang=en', DATE '2026-11-13', 'Public Domain Mark 1.0 is a PDOK rights/status marker on the current API and is not independently a legal warranty for every original 2025 national farmer-declaration parcel, upstream right or insurer reuse; no specific 2025 parcel-file version or scientific CAT model admission established.', false, false),
  ('nl.rvo.brp-gewaspercelen.2025', 'RVO/PDOK BRP Gewaspercelen OGC API Features: exactly one current-live brpgewas Collection metadata GET on 2026-11-13, NOT immutable 2025 final parcel archive', 'automated_api_access', 'allowed', 'https://api.pdok.nl/rvo/gewaspercelen/ogc/v1?f=html&lang=en', DATE '2026-11-13', 'PDOK explicitly provides this public, anonymous, free OGC Features API to commercial and private users subject to the Producten-en-Diensten-Catalogus and fair-use rules. Scope is ONE trusted-main fixed Collection metadata GET, no items, geometry, retries, pagination, schedule or bulk requests.', false, false),
  ('nl.rvo.brp-gewaspercelen.2025', 'RVO/PDOK BRP Gewaspercelen OGC API Features: exactly one current-live brpgewas Collection metadata GET on 2026-11-13, NOT immutable 2025 final parcel archive', 'internal_neon_metadata', 'allowed', 'https://api.pdok.nl/rvo/gewaspercelen/ogc/v1?f=html&lang=en', DATE '2026-11-13', 'Permits storage in private insurance Neon research of one source collection metadata receipt: exact original request/response SHA-256, bytes, UTC, GitHub run and code/contract hashes and boolean structural diagnostics only, no original response body or crops/farmer fields.', false, false),
  ('nl.rvo.brp-gewaspercelen.2025', 'RVO/PDOK BRP Gewaspercelen OGC API Features: exactly one current-live brpgewas Collection metadata GET on 2026-11-13, NOT immutable 2025 final parcel archive', 'internal_neon_source_sample', 'allowed', 'https://api.pdok.nl/rvo/gewaspercelen/ogc/v1?f=html&lang=en', DATE '2026-11-13', 'Only a sanitized research public_metadata sample representing original JSON collection identity and CRS/extent boolean verification is in scope. No provider source JSON bytes, parcel geometry, crop IDs/values, personal details, full 2025 asset or model inputs admitted.', false, false),
  ('nl.rvo.brp-gewaspercelen.2025', 'RVO/PDOK BRP Gewaspercelen OGC API Features: exactly one current-live brpgewas Collection metadata GET on 2026-11-13, NOT immutable 2025 final parcel archive', 'external_raw_redistribution', 'unknown', 'https://api.pdok.nl/rvo/gewaspercelen/ogc/v1?f=html&lang=en', DATE '2026-11-13', 'Do not redistribute original PDOK geometry/feature bodies or claim version-frozen 2025 licence from a public-domain *mark* on the mutable current API metadata. Archived dataset/third-party rights and product-specific repository publication approval not checked.', false, false),
  ('nl.rvo.brp-gewaspercelen.2025', 'RVO/PDOK BRP Gewaspercelen OGC API Features: exactly one current-live brpgewas Collection metadata GET on 2026-11-13, NOT immutable 2025 final parcel archive', 'published_derived_results', 'conditional', 'https://api.pdok.nl/rvo/gewaspercelen/ogc/v1?f=html&lang=en', DATE '2026-11-13', 'Metadata-only research descriptions are acceptable with PDOK/RVO source and no false claim to actual 2025 parcels, insured crop value, observed damage or independently verified EuroCropsV2 data. Published parcel or CAT derivatives need separate exact-version rights, attribution/privacy and science review.', false, false)
